static const char* kCursorFragSrc = R"glsl(
precision highp float;

in  vec2        v_localUV;
flat in float   v_aspect;    // quad w/h — corrects X so 1 iso unit = h/2 px
flat in vec4    v_color;
flat in vec4    v_params;

out vec4 fragColor;

// L1 SDF: solid diamond centred at `c` with half-size `sz` in iso space.
float sdDiamond(vec2 p, vec2 c, float sz)
{
    vec2 d = abs(p - c);
    return (d.x + d.y) - sz;
}

void main()
{
    float inv = 1.0 / v_aspect;
    vec2 p = vec2(v_localUV.x * inv, v_localUV.y);

    // ── Floor ring mode (v_params.w < -0.5) ────────────────────────────────
    // Draws an SDF ellipse ring at the iso floor level of the tile.
    // Floor center in p-space: (0, 1 - aspect/2), derived from tile geometry.
    if (v_params.w < -0.5)
    {
        float floorCY = 1.0 - v_aspect * 0.5;
        float a = inv  * 0.82;          // X semi-axis (82 % of tile half-width)
        float b = v_aspect * 0.5 * 0.82; // Y semi-axis

        // Subtle breathing animation.
        float phase = v_params.z;
        float breathe = 1.0 + 0.03 * sin(phase * 6.283185);
        a *= breathe;
        b *= breathe;

        vec2  q = p - vec2(0.0, floorCY);
        float dist = length(vec2(q.x / a, q.y / b));
        float d = (dist - 1.0) * min(a, b);

        float ringW = v_params.y;
        float mainRing = abs(d) - ringW * 0.5;

        // Outer ring (sharp edge).
        float alpha = smoothstep(0.025, -0.025, mainRing);
        // Soft holographic glow (reduced intensity).
        float glow  = smoothstep(0.20, 0.0, max(mainRing, 0.0)) * 0.35;

        // "Digital scan" sweep effect (more subtle).
        float angle = atan(q.x / a, q.y / b);
        float sweep = smoothstep(0.20, 0.0, abs(fract(angle / 6.283185 + phase * 0.35) - 0.5)) * 0.15;
        glow += sweep;

        // Interior "plasma" fill (semi-transparent holographic look, more subtle).
        float swirl = sin(angle * 3.0 - phase * 12.0) * 0.5 + 0.5;
        float vortex = smoothstep(0.0, -0.20, d) * 0.10 * swirl;
        
        // Secondary "digital pulse" ring (more integrated).
        float d3 = d + 0.12 + 0.04 * cos(angle * 2.0 + phase * 6.0);
        float pulseRing = smoothstep(0.03, -0.03, abs(d3) - 0.01) * 0.18;

        // Inner pulsing core ring.
        float d2 = d + 0.08 + 0.03 * sin(phase * 6.283185 + 0.8);
        float innerRing = abs(d2) - ringW * 0.35;
        float alpha2 = smoothstep(0.02, -0.02, innerRing) * (0.2 + 0.1 * sin(phase * 6.283185));

        alpha = clamp(alpha + alpha2 + glow + vortex + pulseRing, 0.0, 1.0);
        if (alpha < 0.01) discard;
        fragColor = vec4(v_color.rgb, v_color.a * alpha);
        return;
    }

    // ── Ring (AP gauge) mode ────────────────────────────────────────────────
    if (v_params.x < -0.01)
    {
        float innerR  = -v_params.x;          // inner radius in iso units
        float ringW   =  v_params.y;           // ring width in iso units
        float arcFrac =  v_params.z;           // [0..1] fraction of TU remaining

        float r    = length(p);
        float ring = abs(r - (innerR + ringW * 0.5)) - ringW * 0.5;

        // Angle: 0 = top (12 o'clock), increasing clockwise.
        // atan(x, -y): at top p=(0,-1) → atan(0,1)=0; at right p=(inv,0) → π/2.
        float angle     = atan(p.x, -p.y);
        float normAngle = mod(angle / 6.28318530718 + 1.0, 1.0);

        // Faint background ring (full circle — shows TU maximum).
        float bgAlpha  = smoothstep(0.025, -0.025, ring) * 0.18;

        // Bright arc proportional to remaining TU.
        float arcMask  = step(normAngle, arcFrac);
        float arcAlpha = smoothstep(0.025, -0.025, ring) * arcMask;
        float glow     = smoothstep(0.09, 0.0, max(ring, 0.0)) * arcMask * 0.35;

        float alpha = clamp(arcAlpha + bgAlpha + glow, 0.0, 1.0);
        if (alpha < 0.01) discard;
        fragColor = vec4(v_color.rgb, v_color.a * alpha);
        return;
    }

    // ── 4-tip marker mode ───────────────────────────────────────────────────
    float markerSize = v_params.x;
    float baseFrac   = v_params.y;
    float animFrac   = v_params.z;
    float phase      = v_params.w;

    // Animated fraction: all 4 markers move together (breathing effect).
    float frac = baseFrac + animFrac * sin(phase * 6.28318530718);

    // Marker centres in iso space — equidistant from tile centre in pixels.
    vec2 cN = vec2(0.0,       -frac);
    vec2 cS = vec2(0.0,       +frac);
    vec2 cW = vec2(-frac * inv, 0.0);
    vec2 cE = vec2(+frac * inv, 0.0);

    float d = min(min(sdDiamond(p, cN, markerSize),
                      sdDiamond(p, cS, markerSize)),
                  min(sdDiamond(p, cW, markerSize),
                      sdDiamond(p, cE, markerSize)));

    float alpha = smoothstep(0.025, -0.025, d);
    float glow  = smoothstep(0.10, 0.0, max(d, 0.0)) * 0.40;

    alpha = clamp(alpha + glow, 0.0, 1.0);
    if (alpha < 0.01) discard;
    fragColor = vec4(v_color.rgb, v_color.a * alpha);
}
)glsl";

static const char* kEmissive_glowFragSrc = R"glsl(
uniform vec3  u_tint;
uniform float u_intensity;

in  vec2 v_local;      // -1..1 across the quad
out vec4 out_color;

void main()
{
    float d = length(v_local);
    // Bright soft core (gaussian-ish) with a smooth edge cut at the quad border
    // so the square geometry never shows.
    float core = exp(-d * d * 2.2);
    float edge = smoothstep(1.0, 0.0, d);
    float a = core * edge;
    out_color = vec4(u_tint * (a * u_intensity), 1.0);
}
)glsl";

static const char* kGlobe_sphereFragSrc = R"glsl(
in  vec2 v_pixel;
out vec4 fragColor;

uniform vec2      u_globeCenter;
uniform float     u_globeRadius;
uniform float     u_camLat;
uniform float     u_camLon;
uniform vec3      u_sunDir;
uniform float     u_time;
uniform float     u_mipLevel;

uniform sampler2D u_bathymetry;
uniform sampler2D u_diffuse;
uniform sampler2D u_night;
uniform sampler2D u_clouds;

// Rotate a view-space normal by camera (lat then lon) to world space.
// camLat: rotation around X axis (pitch south/north)
// camLon: rotation around Y axis (yaw east/west)
vec3 applyCameraRotation(vec3 n, float camLat, float camLon)
{
    // Rotate around X by camLat
    float sl = sin(camLat);  float cl = cos(camLat);
    float y1 =  cl * n.y - sl * n.z;
    float z1 =  sl * n.y + cl * n.z;
    n = vec3(n.x, y1, z1);

    // Rotate around Y by camLon
    float so = sin(camLon);  float co = cos(camLon);
    float x2 =  co * n.x + so * n.z;
    float z2 = -so * n.x + co * n.z;
    n = vec3(x2, n.y, z2);

    return n;
}

void main()
{
    // Distance from globe disk centre (pixel space)
    vec2  d = v_pixel - u_globeCenter;
    float r = length(d) / u_globeRadius;
    if (r > 1.0) discard;
    float edgeAlpha = 1.0 - smoothstep(0.985, 1.0, r);

    // Orthographic inverse: pixel → unit-sphere surface normal in view space.
    // View space matches Globe::polarToCart(): +X right, +Y down, +Z front.
    float nz      = sqrt(max(0.0, 1.0 - r * r));
    vec3  n_view  = vec3(d.x / u_globeRadius, d.y / u_globeRadius, nz);

    // Rotate to world space using camera orientation.
    vec3 n_world = applyCameraRotation(n_view, -u_camLat, u_camLon);

    // World normal → equirectangular UV.
    float lat  = asin(clamp(n_world.y, -1.0, 1.0));
    // Bias atan only at the exact pole singularity; preserves accuracy elsewhere.
    float bias = (abs(n_world.x) + abs(n_world.z) < 1e-7) ? 1e-5 : 0.0;
    float lon  = atan(n_world.x, n_world.z + bias);           // [-π, +π]
    // OXCE xcom2 globe rules use inverted latitude compared to real-world
    // equirectangular imagery (London is stored near -49°, not +51°).
    // Keep geometry/clicks in game coordinates, but sample NASA textures with
    // latitude flipped so visual land/water matches the gameplay map.
    vec2  uv  = vec2((lon + 3.14159265) / 6.28318530,        // [0, 1]
                     (1.57079633 + lat) / 3.14159265);        // [0, 1]

    // Sample all layers at the selected mip level.
    vec3  bathy  = textureLod(u_bathymetry, uv, u_mipLevel).rgb;
    vec3  diff   = textureLod(u_diffuse,    uv, u_mipLevel).rgb;
    vec3  night  = textureLod(u_night,      uv, u_mipLevel).rgb;
    // Cloud layer drifts longitudinally; GL_REPEAT handles seamless wrap.
    // One wrap is ~37 minutes: visible in play, calm enough for Geoscape.
    vec2  cloudUV = vec2(uv.x + u_time * 0.00045, uv.y);
    vec4  cloud   = textureLod(u_clouds, cloudUV, u_mipLevel);

    // Stylized TFTD composite.  Real satellite colour is too bright and
    // documentary-looking next to the low-res Geoscape UI, so keep the ocean
    // dominant and treat land as a muted overlay until a real land mask ships.
    float landWarmth = diff.r * 1.15 + diff.g * 0.85 - diff.b * 1.25;
    float landMask = smoothstep(0.10, 0.28, landWarmth);

    vec3 ocean = bathy * vec3(0.16, 0.42, 0.62) + vec3(0.00, 0.018, 0.040);
    vec3 dryLand = diff * vec3(0.48, 0.56, 0.50) + vec3(0.00, 0.015, 0.020);

    // Preserve a hint of real tropical greenery.  The mask is intentionally
    // soft: enough to make Amazon/Congo/Indonesia read green, not enough to
    // pull the globe back into raw satellite-photo colours.
    float diffMax = max(max(diff.r, diff.g), diff.b);
    float diffMin = min(min(diff.r, diff.g), diff.b);
    float diffLuma = dot(diff, vec3(0.299, 0.587, 0.114));
    float diffSat = diffMax - diffMin;
    float greenHue =
        smoothstep(-0.015, 0.070, diff.g - diff.r * 0.88) *
        smoothstep(-0.030, 0.075, diff.g - diff.b * 0.78);
    float notSnow = (1.0 - smoothstep(0.50, 0.74, diffLuma)) * smoothstep(0.045, 0.155, diffSat);
    float vegetation = landMask * greenHue * notSnow;
    vec3 greenLand = diff * vec3(0.30, 0.92, 0.50) + vec3(0.00, 0.055, 0.025);
    vec3 land = mix(dryLand, greenLand, vegetation * 0.78);
    vec3 surface = mix(ocean, land, landMask);

    // Desaturate and cool the whole globe toward TFTD's sonar/navy mood.
    float luma = dot(surface, vec3(0.299, 0.587, 0.114));
    surface = mix(vec3(luma), surface, 0.72);
    surface *= vec3(0.72, 0.92, 1.05);

    // Day / night terminator.  Keep it wider than the physical value: a
    // razor-sharp terminator looks like a black stripe at Geoscape scale.
    float sunDot   = dot(n_world, u_sunDir);
    float dayFactor = smoothstep(-0.46, 0.24, sunDot);

    // Cloud opacity comes from the WebP alpha channel.  The source cloud map is
    // very dense, so compress it hard instead of washing the globe to white.
    float cloudDensity = smoothstep(0.34, 0.96, cloud.a) * 0.24;
    vec3 cloudColor = vec3(0.66, 0.86, 0.90);

    vec3 daySide = mix(surface, cloudColor, cloudDensity * dayFactor) * (0.42 + dayFactor * 0.76);
    vec3 nightSurface = surface * vec3(0.42, 0.48, 0.56);
    vec3 nightSide = (nightSurface + vec3(0.005, 0.030, 0.055) + night * vec3(0.18, 0.62, 0.78)) * (1.0 - dayFactor);

    // Darken the limb and add a thin cyan atmospheric rim inside the disk.
    float limb = smoothstep(0.03, 0.55, nz);
    vec3 rim = vec3(0.00, 0.16, 0.20) * pow(1.0 - nz, 3.0);

    fragColor = vec4((daySide + nightSide) * (0.42 + limb * 0.58) + rim, edgeAlpha);
}
)glsl";

static const char* kTexturedFragSrc = R"glsl(
uniform sampler2D u_tex;
uniform float     u_darken;
uniform vec3      u_tint;
uniform float     u_alpha;   // Calypso: overall alpha multiply; unset(0) => 1.0 (callers unaffected)
uniform vec2      u_uvScroll; // Calypso: UV offset for drifting layers (unset(0) => none)
uniform vec3      u_tintEdge; // Calypso: radial-gradient outer colour (inner = u_tint)
uniform float     u_radial;   // Calypso: 0 = flat tint (unset default); >0 = radial mix amount
// Calypso P30: optional per-edge isometric clip (used to cut a blood/scorch decal along the
// specific tile edge(s) where a door is, instead of masking the whole tile diamond — that
// kept the splat's natural shape on the other sides instead of a solid filled diamond).
// u_clipEdges = (W,N,E,S) flags; unset(0,0,0,0) = no clip, so every other caller is
// unaffected. Centre + half-extents are the tile floor diamond in window pixels (gl_FragCoord).
// Each active edge discards the half-plane beyond it (toward that neighbour tile): the four
// neighbour directions in window coords are W(-hx,+hy) N(+hx,+hy) E(+hx,-hy) S(-hx,-hy); the
// dividing line is the perpendicular bisector, i.e. dot(frag-centre, dir) > 0.5*|dir|^2.
uniform vec4      u_clipEdges;
uniform vec2      u_clipCenter;
uniform vec2      u_clipHalf;
in      vec2      v_uv;
out     vec4      out_color;

void main()
{
    if (any(greaterThan(u_clipEdges, vec4(0.0))))
    {
        vec2  f  = gl_FragCoord.xy - u_clipCenter;
        float r2 = 0.5 * (u_clipHalf.x * u_clipHalf.x + u_clipHalf.y * u_clipHalf.y);
        if (u_clipEdges.x > 0.0 && dot(f, vec2(-u_clipHalf.x,  u_clipHalf.y)) > r2) discard; // west
        if (u_clipEdges.y > 0.0 && dot(f, vec2( u_clipHalf.x,  u_clipHalf.y)) > r2) discard; // north
        if (u_clipEdges.z > 0.0 && dot(f, vec2( u_clipHalf.x, -u_clipHalf.y)) > r2) discard; // east
        if (u_clipEdges.w > 0.0 && dot(f, vec2(-u_clipHalf.x, -u_clipHalf.y)) > r2) discard; // south
    }
    vec4 c = texture(u_tex, v_uv + u_uvScroll);
    // Unset uniform (0,0,0) means "no tint" → white, so untinted callers are
    // unaffected; tinted callers pass a non-zero colour.
    vec3 tint = all(equal(u_tint, vec3(0.0))) ? vec3(1.0) : u_tint;
    // Calypso: radial colour ramp (u_tint at the centre → u_tintEdge at the rim).
    // u_radial unset (0) leaves every existing caller on the flat-tint path above.
    if (u_radial > 0.0)
    {
        float d = clamp(length(v_uv - vec2(0.5)) * 2.0 * u_radial, 0.0, 1.0);
        tint = mix(u_tint, u_tintEdge, smoothstep(0.0, 1.0, d));
    }
    float am = (u_alpha <= 0.0) ? 1.0 : u_alpha;   // unset → opaque
    out_color = vec4(c.rgb * tint * (1.0 - u_darken), c.a * am);
}
)glsl";

static const char* kTile_atlasFragSrc = R"glsl(
uniform sampler2D u_atlas;
uniform sampler2D u_shadeTable;
uniform float     u_animFrame;
uniform vec2      u_tileUVSize;

in vec2  v_uv;
in float v_shade;
in float v_animFrameCount;
in float v_alphaMask;

out vec4 fragColor;

void main()
{
    // Discard tiles marked as fully transparent by the MCD opacity flag.
    if (v_alphaMask < 0.5) discard;

    // Resolve the current animation frame and offset the UV horizontally.
    float frame = floor(u_animFrame * v_animFrameCount);
    vec2 uv = v_uv + vec2(frame * u_tileUVSize.x, 0.0);

    // Sample atlas: R channel holds the palette index normalised to [0, 1].
    // Multiply by 255 and round to recover the integer index.
    float palNorm = texture(u_atlas, uv).r;

    // Palette index 0 is always transparent.
    if (palNorm < (0.5 / 255.0)) discard;

    // Undiscovered tiles (v_shade==16 from CPU side) render as opaque black.
    // ShadeTable::get returns _black (0xFF000000) for shade>=16; emulate that
    // exactly here so canopy silhouettes occlude interiors the player has not
    // discovered yet, matching painter's blit behaviour.
    if (v_shade >= 15.5)
    {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    // Shade-table lookup using texel-centre coordinates to avoid bleed
    // between adjacent entries (both atlas and shade table use GL_NEAREST,
    // but the explicit + 0.5 guard is cheap insurance).
    float shadeU = (v_shade + 0.5) / 16.0;
    float shadeV = (palNorm * 255.0 + 0.5) / 256.0;
    vec4 shaded = texture(u_shadeTable, vec2(shadeU, shadeV));

    fragColor = vec4(shaded.rgb, shaded.a);
}
)glsl";

static const char* kTile_atlas_rgbaFragSrc = R"glsl(
uniform sampler2D u_atlas;
uniform sampler2D u_shadeCurve;  // unit 3: 16×1 night ramp (Phase 22, P5)
uniform float     u_animFrame;
uniform vec2      u_tileUVSize;
// Phase 25 R3: tangent-space normal map (unit 4; LINEAR non-sRGB). u_hasNormalMap
// is reset per draw group in Map::drawTileGLPass so non-mapped datasets stay flat.
uniform sampler2D u_normalMap;
uniform vec3      u_sunDir;        // normalised in-shader
uniform int       u_hasNormalMap;  // 0 = skip relief; 1 = apply
// Phase 25 R6: material emissive (unit 5). RGB = glow colour, A = intensity.
// Added AFTER shade/relief so the tile self-lights in shadow; lands in the HDR
// SSAA buffer (R0) where the >1.0 highlights bloom. u_hasEmissive reset per group.
uniform sampler2D u_emissive;
uniform int       u_hasEmissive;       // 0 = none; 1 = add glow
uniform float     u_emissiveStrength;  // global live-tunable multiplier

in vec2  v_uv;
in vec2  v_localUV;
in float v_shade;
in float v_animFrameCount;
in float v_alphaMask;

out vec4 fragColor;

void main()
{
    if (v_alphaMask < 0.5) discard;

    float frame = floor(u_animFrame * v_animFrameCount);
    vec2 uv = v_uv + vec2(frame * u_tileUVSize.x, 0.0);

    vec4 c = texture(u_atlas, uv);

    // A value above 1.0 in alphaMask marks a floor-like O_OBJECT layer. Its
    // source still has the ordinary diamond mask, but the material fades out
    // well inside that diamond so it dissolves into the O_FLOOR below instead
    // of painting a visible, tile-sized rhombus.
    if (v_alphaMask > 1.5)
    {
        // Map the unit quad to the 2:1 isometric diamond. Each component is
        // 0..1 inside it; edge is the distance to the nearest diamond side.
        float d = 2.5 * (v_localUV.y - 0.8);
        vec2 diamondUV = vec2(v_localUV.x - d, v_localUV.x + d);
        float edge = min(min(diamondUV.x, diamondUV.y),
                         min(1.0 - diamondUV.x, 1.0 - diamondUV.y));
        c.a *= smoothstep(0.10, 0.35, edge);
    }
    // Discard only truly-transparent texels (covers the geometry-overdraw
    // border around each cell and clamp-to-edge samples outside the mask).
    if (c.a < 0.01) discard;

    // Undiscovered tiles (v_shade==16 from CPU side) render as opaque black.
    if (v_shade >= 15.5)
    {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    // Phase 22 (P5): luminance-ramp darkening from the palette shade table so
    // HD overlay tiles match the brightness of adjacent blend tiles at night.
    float shadeF  = texture(u_shadeCurve, vec2((v_shade + 0.5) / 16.0, 0.5)).r;

    // Phase 25 R3/R4: optional normal-map diffuse relief + ambient occlusion.
    // RGB decodes the tangent-space normal (0.5 + N*0.5) → Lambert against the sun;
    // A is AO (crevice darkening). relief = AO * (0.6 ambient + 0.4 * max(N·L, 0)).
    // u_hasNormalMap==0 → identity.
    float relief = 1.0;
    if (u_hasNormalMap == 1)
    {
        vec4  nm = texture(u_normalMap, uv);
        vec3  n  = normalize(nm.rgb * 2.0 - 1.0);
        float ao = nm.a;                                   // R4: ambient occlusion
        relief = ao * (0.6 + 0.4 * max(dot(n, normalize(u_sunDir)), 0.0));
    }
    vec3 lit = c.rgb * shadeF * relief;

    // Phase 25 R6: add material emission on top of the lit colour (self-lit, so it
    // survives night/shadow). Premultiplied by its own alpha; the global strength
    // can push it past 1.0 so the HDR tonemap (R0) blooms lava/bioluminescence.
    if (u_hasEmissive == 1)
    {
        vec4 em = texture(u_emissive, uv);
        lit += em.rgb * em.a * u_emissiveStrength;
    }
    fragColor = vec4(lit, c.a);
}
)glsl";

static const char* kTile_blendFragSrc = R"glsl(
uniform sampler2D u_atlas;       // unit 0: RGBA overlay atlas
uniform sampler2D u_noise;       // unit 2: tiling noise (GL_REPEAT)
uniform sampler2D u_shadeCurve;  // unit 3: 16×1 night ramp
uniform vec2  u_tileUVSize;
uniform float u_animFrame;
// Phase 25 R3: tangent-space normal map (unit 4; LINEAR non-sRGB).
uniform sampler2D u_normalMap;
uniform vec3      u_sunDir;
uniform int       u_hasNormalMap;

in vec2  v_uv;
in vec2  v_neighbourUV;
in vec2  v_diamondUV;
in vec2  v_worldUV;
flat in uint v_wangMask;
in float v_shade;
in float v_animFrameCount;
in float v_alphaMask;
in float v_feather;
in float v_noiseScale;
in float v_noiseAmp;

out vec4 fragColor;

// Bilinear corner field in diamond-local space.
// Returns 0 (self cell) → 1 (neighbour cell).
// Bit mapping:  NW=bit3, NE=bit2, SE=bit1, SW=bit0.
// §22.0.2 calibration (derived from Camera::convertMapToScreen — screenX=16x-16y,
// screenY=8x+8y — and computeWangMask): grid-N renders screen upper-right, W
// upper-left, E lower-right, S lower-left, so the shared Wang corners land on the
// diamond VERTICES as  NW→top  NE→right  SE→bottom  SW→left.  toDiamond maps those
// vertices to d-corners  left→(0,0) top→(1,0) bottom→(0,1) right→(1,1), giving the
// bilinear placement below (the prior nw/ne/sw/se order was rotated 90°).
float cornerField(vec2 d, uint m)
{
    float nw = float((m >> 3u) & 1u);
    float ne = float((m >> 2u) & 1u);
    float se = float((m >> 1u) & 1u);
    float sw = float( m        & 1u);
    //  d(0,0)=left=SW   d(1,0)=top=NW   d(0,1)=bottom=SE   d(1,1)=right=NE
    return mix(mix(sw, nw, d.x), mix(se, ne, d.x), d.y);
}

void main()
{
    if (v_alphaMask < 0.5) discard;

    float frame    = floor(u_animFrame * v_animFrameCount);
    vec2  frameOff = vec2(frame * u_tileUVSize.x, 0.0);

    vec4 self = texture(u_atlas, v_uv          + frameOff);
    vec4 nbr  = texture(u_atlas, v_neighbourUV + frameOff);

    float fld = cornerField(v_diamondUV, v_wangMask);
    // Noise sampled at world-tile coord so it stays still under camera pan (P14).
    float nz  = texture(u_noise, v_worldUV * v_noiseScale).r - 0.5;
    // Clamp feather ≥ 0.001 to guard smoothstep UB when edge0 == edge1 (P15).
    float fe  = max(v_feather, 0.001);

    // §25 edge-localised blend. cornerField is 0.5 at a single-foreign tile's
    // CENTRE (bilinear of 1/0 corners), so smoothstep(0.5±fe, fld) smeared the mix
    // halfway across the tile and gave a bright core + wide halo that read as a
    // diamond. Remap so only the FOREIGN half (fld 0.5→1) blends: `edge` is 0
    // through the self interior and 1 at the shared seam — the tile keeps its own
    // colour at its centre and dissolves only toward the boundary.
    float edge = clamp((fld - 0.5) * 2.0, 0.0, 1.0);
    float w    = smoothstep(0.5 - fe, 0.5 + fe, edge + nz * v_noiseAmp);

    // Seam-symmetry: cap the mix at 0.5 so each tile reaches at most a 50/50 blend
    // at the seam (edge → 1 there). Both neighbours render an IDENTICAL 50/50
    // colour on the seam, so the result is independent of draw order — `baseline:
    // none` datasets (SAND) write no floor depth, so the blend pass is a pure
    // painter's-order draw, and before the cap the front tile's diamond occluded
    // the back tile's feather on one diagonal only. 0.5 is the unique cap that
    // makes the seam pixel agree from both sides (0.5·B+0.5·A == 0.5·A+0.5·B).
    vec4 c = mix(self, nbr, clamp(w, 0.0, 1.0) * 0.5);
    if (c.a < 0.01) discard;

    if (v_shade >= 15.5)
    {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }
    float shadeF = texture(u_shadeCurve, vec2((v_shade + 0.5) / 16.0, 0.5)).r;

    // Phase 25 R3/R4: blend self+neighbour normals AND AO with the SAME w (and 0.5
    // cap) as the colour mix above so relief + occlusion stay continuous across the
    // seam, then Lambert: AO * (0.6 + 0.4 * max(N·L, 0)).
    float relief = 1.0;
    if (u_hasNormalMap == 1)
    {
        vec4 nmSelf = texture(u_normalMap, v_uv          + frameOff);
        vec4 nmNbr  = texture(u_normalMap, v_neighbourUV + frameOff);
        vec4 nm = mix(nmSelf, nmNbr, clamp(w, 0.0, 1.0) * 0.5);
        vec3  n  = normalize(nm.rgb * 2.0 - 1.0);
        float ao = nm.a;                                   // R4: ambient occlusion
        relief = ao * (0.6 + 0.4 * max(dot(n, normalize(u_sunDir)), 0.0));
    }
    fragColor = vec4(c.rgb * shadeF * relief, c.a);
}
)glsl";

static const char* kUnderwater_gradeFragSrc = R"glsl(
uniform sampler2D u_scene;
uniform int       u_underwater;       // 1 = underwater mission (grade on); 0 = dry land (passthrough)
uniform float     u_strength;
uniform float     u_time;
uniform vec2      u_res;
uniform float     u_caustics;
uniform float     u_refract;
uniform float     u_bubbles;
uniform float     u_snow;
uniform float     u_godray;           // light shafts from the surface
uniform float     u_bloom;            // glow on bright spots
uniform float     u_breath;           // slow global light "breathing" pulse
uniform float     u_chroma;           // subtle chromatic aberration at edges
uniform float     u_unitbub;          // aquanaut breathing-bubble amount (own knob)
uniform int       u_unitCount;        // # of visible aquanauts
uniform vec2      u_unitPos[12];      // their screen UV (v_uv space; y up)
uniform float     u_shock;            // E2: explosion shockwave-ring distortion amount
uniform int       u_swCount;          // # active shockwaves
uniform vec2      u_swCenter[4];      // their v_uv centres
uniform float     u_swAge[4];         // 0..1 ring expansion
uniform int       u_hdr;              // R0: 1 = u_scene is RGBA16F (values may exceed 1.0) → tonemap
in      vec2      v_uv;
out     vec4      out_color;

// R0 tonemap: filmic shoulder. Exact identity below the knee, then a smooth
// exponential rolloff to 1.0 above it. Applied to the max channel so hue +
// saturation are preserved and the result can never exceed 1.0 (no clip on the
// 8-bit default framebuffer). C1-continuous at the knee (slope 1).
//
// Identity-below-1 AND a soft rolloff-above-1 that keeps output <= 1 is
// mathematically impossible (no output headroom above 1), so the shoulder must
// start a little below 1.0. knee=0.90 makes everything <= 0.90 unchanged and
// compresses [0.90, 1.0] by at most ~3.7% at pure white — imperceptible, and the
// graded underwater scene (dimmed + tinted) almost never reaches 0.90 anyway.
// That small cost buys a coloured (non-clipping) rolloff for the bloom/emissive
// overbrights, which is the whole point of R0. A no-op in LDR (u_hdr==0).
vec3 tonemapShoulder(vec3 c)
{
    const float knee = 0.90;
    float m = max(max(c.r, c.g), c.b);
    if (m <= knee) return c;
    float range  = 1.0 - knee;                       // output headroom above knee
    float mapped = knee + range * (1.0 - exp(-(m - knee) / range));
    return c * (mapped / m);
}

float hash21(vec2 p)
{
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// Layered animated ridged sine net -> caustic light pattern.
float caustics(vec2 uv, float t)
{
    vec2 p = uv * vec2(7.0, 5.0);
    float c = 0.0;
    for (int i = 0; i < 3; ++i)
    {
        float fi = float(i);
        vec2 q = p + fi * 1.7;
        float a = sin(q.x * 2.1 + t * 0.9 + sin(q.y * 1.7 - t * 0.6));
        float b = sin(q.y * 1.9 - t * 0.7 + sin(q.x * 2.3 + t * 0.5));
        c += a * b;
        p *= 1.6;
    }
    c = pow(clamp(c / 3.0 * 0.5 + 0.5, 0.0, 1.0), 3.0);
    return c;
}

// Soft dots on a hashed grid, scrolling at vel (uv/sec) - used for marine snow.
float particleLayer(vec2 uv, float t, float grid, vec2 vel, float size,
                    float seed, float aspect)
{
    vec2 g = uv * grid + vel * t * grid;
    vec2 cell = floor(g);
    vec2 f = fract(g);
    float r1 = hash21(cell + seed);
    float r2 = hash21(cell + seed + 5.2);
    float br = hash21(cell + seed + 9.1);
    vec2 c = vec2(0.2 + 0.6 * r1, 0.2 + 0.6 * r2);
    vec2 d = (f - c) * vec2(aspect, 1.0);
    return smoothstep(size, 0.0, length(d)) * (0.35 + 0.65 * br);
}

// Bubbles from vents distributed over the seabed: each active cell is a vent - a
// hollow bubble rises a short distance from its base point, pops/fades, and the
// vent re-fires. Sparse (only ~density of cells vent). Caller masks by the scene
// so vents sit on the floor, not the black void.
float bubbleLayer(vec2 uv, float t, float grid, float speed, float size,
                  float seed, float aspect, float density)
{
    vec2 g = uv * grid;
    vec2 cell = floor(g);
    vec2 f = fract(g);
    if (hash21(cell + seed + 3.7) > density) return 0.0;    // only some cells vent
    float r1 = hash21(cell + seed);
    float r2 = hash21(cell + seed + 5.2);
    float rt = fract(t * speed * (0.7 + 0.6 * r2) + r1);    // rise progress (loops)
    vec2 base = vec2(0.20 + 0.60 * r1, 0.12);               // vent point in the cell
    vec2 c = base + vec2(0.05 * sin(t * 1.2 + r1 * 6.28) * rt, rt * 0.64);
    float sz = size * (0.6 + 0.3 * r2);                     // capped size variety
    vec2 d = (f - c) * vec2(aspect, 1.0);
    float dist = length(d) / sz;
    float er  = (dist - 0.80) / 0.16;
    float rim = exp(-er * er);                              // hollow ring
    vec2  hp  = (d / sz) - vec2(-0.30, 0.30);               // highlight
    float hi  = exp(-(length(hp) / 0.26) * (length(hp) / 0.26));
    float fade = smoothstep(0.0, 0.12, rt) * (1.0 - smoothstep(0.75, 1.0, rt));
    return (rim * 0.85 + hi * 0.9) * step(dist, 1.25) * fade;
}

// HD breathing bubbles rising from an aquanaut at P (uv, y up). Each bubble runs
// its OWN continuous lifecycle (born small -> inflate -> rise -> DEFLATE to
// nothing) on its own period + phase, so they are never in sync — they pop/deflate
// one at a time, never all at once. Varied size + a slow shape wobble.
float unitBubbles(vec2 uv, vec2 P, float seed, float aspect, float t)
{
    float acc = 0.0;
    for (int k = 0; k < 4; ++k)
    {
        float fk = float(k);
        float rk = fract(sin((seed + fk * 12.9) * 91.7) * 43758.5453);  // per-bubble
        float period = 3.0 + 2.5 * rk;                      // each bubble's own life (s)
        float life = fract(t / period + rk);                // 0..1, staggered -> desynced
        float base = 0.00225 + 0.00375 * fract(rk * 7.13 + 0.3);  // different sizes (half)
        // born small -> inflate -> deflate away near the end of ITS life
        float inflate = smoothstep(0.0, 0.10, life);
        float deflate = 1.0 - smoothstep(0.62, 1.0, life);
        float sz = max(base * inflate * deflate * (1.0 + 0.25 * life), 1e-4);
        float wob = 0.26 * sin(t * 2.0 + rk * 6.28 + fk);   // living shape wobble
        vec2  sq = vec2(1.0 + wob, 1.0 / (1.0 + wob));
        float sway = 0.006 * sin(t * 1.6 + fk + rk * 6.28);
        vec2  bc = P + vec2(sway, 0.010 + life * 0.085);    // rises over its life
        vec2  d  = (uv - bc) * vec2(aspect, 1.0) * sq;
        float dn = length(d) / sz;
        float er = (dn - 0.80) / 0.16;
        float rim = exp(-er * er);                          // hollow ring
        vec2  hp = (d / sz) - vec2(-0.30, 0.30);
        float hi = exp(-(length(hp) / 0.26) * (length(hp) / 0.26));
        acc += (rim * 0.85 + hi * 0.9) * step(dn, 1.25);
    }
    return acc;
}

// Light shafts from the surface: a few soft, slightly-tilted, swaying beams,
// strong at the top of the screen (where light enters) and fading downward.
float godrays(vec2 uv, float t)
{
    float r = 0.0;
    for (int i = 0; i < 4; ++i)
    {
        float fi = float(i);
        float x0 = 0.18 + 0.22 * fi + 0.04 * sin(t * 0.3 + fi * 1.7);
        float w  = 0.05 + 0.018 * fi;
        float e  = (uv.x - x0 - 0.10 * (1.0 - uv.y)) / w;   // tilt with depth
        r += exp(-e * e);
    }
    return r * smoothstep(0.0, 0.55, uv.y);                 // top-lit, fade down
}

// Cheap single-pass bloom: golden-angle disk taps of the scene, keep the bright
// part above a threshold, average -> soft glow added back over the graded colour.
vec3 bloomGlow(vec2 uv, float radius, float aspect)
{
    vec3 acc = vec3(0.0);
    for (int i = 0; i < 12; ++i)
    {
        float a  = float(i) * 2.39996323;                  // golden angle
        float rr = sqrt((float(i) + 0.5) / 12.0) * radius;
        vec2  o  = vec2(cos(a) / aspect, sin(a)) * rr;
        acc += max(texture(u_scene, uv + o).rgb - 0.62, 0.0);
    }
    return acc / 12.0;
}

void main()
{
    // Dry-land missions: this pass is just the SSAA downsample — no underwater grade,
    // caustics, god-rays, refraction or snow (they read as "rays/waves in the air").
    if (u_underwater == 0)
    {
        vec3 dry = texture(u_scene, v_uv).rgb;
        if (u_hdr == 1) dry = tonemapShoulder(dry);   // R0: still tonemap on dry land (emissive may blow out)
        out_color = vec4(dry, 1.0);
        return;
    }
    float s = clamp(u_strength, 0.0, 1.0);
    float aspect = u_res.x / max(u_res.y, 1.0);
    float breath = 1.0 + u_breath * 0.08 * sin(u_time * 0.6);   // slow light pulse

    // 0. refraction: gently wobble the sample UV (looking through moving water)
    vec2 uv = v_uv;
    if (u_refract > 0.0)
    {
        float w = 0.0018 * u_refract;
        uv += vec2(sin(v_uv.y * 11.0 + u_time * 1.3),
                   cos(v_uv.x * 13.0 + u_time * 1.1)) * w;
    }
    // 0b. E2 shockwave: each blast warps the scene in an expanding ring (a hydraulic
    //     compression wave). Underwater only (s>0). Sample UV pushed outward at the front.
    if (u_shock > 0.0 && s > 0.0)
    {
        for (int i = 0; i < 4; ++i)
        {
            if (i >= u_swCount) break;
            vec2  rel = v_uv - u_swCenter[i];
            float dd  = length(vec2(rel.x * aspect, rel.y));   // circular in screen space
            float rad = u_swAge[i] * 0.55;                      // ring expands outward
            float ring  = exp(-pow((dd - rad) / 0.05, 2.0));    // thin gaussian front
            float decay = 1.0 - u_swAge[i];                     // fades as it grows
            vec2  dir = dd > 1e-4 ? rel / dd : vec2(0.0);
            uv += dir * ring * decay * u_shock * 0.03;
        }
    }
    vec3 c;
    if (u_chroma > 0.0)
    {
        vec2 off = (v_uv - 0.5) * u_chroma * 0.010;        // edge-weighted RGB split
        c = vec3(texture(u_scene, uv + off).r,
                 texture(u_scene, uv).g,
                 texture(u_scene, uv - off).b);
    }
    else
    {
        c = texture(u_scene, uv).rgb;
    }
    float lum0 = dot(c, vec3(0.299, 0.587, 0.114));

    // 1. desaturate
    c = mix(c, vec3(lum0), 0.12 + 0.50 * s);

    // 2. colour absorption (warm dies first) + dim
    vec3  tint = vec3(0.88 - 0.46 * s, 0.96 - 0.10 * s, 1.02);
    float dim  = 0.94 - 0.34 * s;
    c *= tint * dim;

    // 3. depth fog - thicker toward the top (farther/deeper in iso)
    vec3  fogCol = vec3(16.0, 56.0, 74.0) / 255.0;
    float fogAmt = (0.18 + 0.52 * s) * (v_uv.y * 0.78 + 0.22);
    c = mix(c, fogCol, clamp(fogAmt, 0.0, 1.0));

    float surf = smoothstep(0.04, 0.30, lum0);   // "there is scene here" mask
    // additive in-water particulate (snow, bubbles) must sit UNDER the depth
    // darkening/fog so it doesn't read as bright white floating on top
    float waterLit = dim * (1.0 - 0.45 * clamp(fogAmt, 0.0, 1.0));

    // 4. caustics - bright light-net on lit surfaces
    if (u_caustics > 0.0)
    {
        float net = caustics(v_uv, u_time);
        c += net * surf * (0.45 + 0.55 * v_uv.y)
             * u_caustics * breath * vec3(0.22, 0.46, 0.52);   // shimmer with the pulse
    }

    // 5. marine snow - slow drifting motes (two parallax layers)
    if (u_snow > 0.0)
    {
        float sn  = particleLayer(v_uv, u_time, 26.0, vec2(0.010, 0.018), 0.045, 1.0, aspect);
        sn += 0.6 * particleLayer(v_uv, u_time, 40.0, vec2(-0.014, 0.026), 0.035, 7.0, aspect);
        c += sn * u_snow * waterLit * vec3(0.45, 0.56, 0.60);
    }

    // 6. bubbles - hollow, rising from vents distributed across the SEABED (the
    //    `surf` mask keeps them on the floor, not the bottom edge of the screen)
    // seabed vents (OFF by default - screen-anchored; re-enable once world-anchored)
    if (u_bubbles > 0.0)
    {
        float bz  = bubbleLayer(v_uv, u_time,  7.0, 0.10, 0.30, 21.0, aspect, 0.10);
        bz += 0.8 * bubbleLayer(v_uv, u_time, 11.0, 0.13, 0.22, 33.0, aspect, 0.09);
        c += bz * surf * u_bubbles * waterLit * vec3(0.45, 0.62, 0.72);
    }
    // small breathing puffs from each visible aquanaut (our HD replacement for the
    // vanilla sprite bubbles, which are suppressed on this build)
    if (u_unitbub > 0.0)
    {
        for (int i = 0; i < 12; ++i)
        {
            if (i >= u_unitCount) break;
            c += unitBubbles(v_uv, u_unitPos[i], float(i) * 0.137, aspect, u_time)
                 * u_unitbub * waterLit * vec3(0.42, 0.60, 0.70);
        }
    }

    // 7. god rays — light shafts from the surface (shimmer with the pulse)
    if (u_godray > 0.0)
        c += godrays(v_uv, u_time) * u_godray * breath * vec3(0.16, 0.32, 0.40);

    // 8. bloom — soft glow on bright spots
    if (u_bloom > 0.0)
        c += bloomGlow(uv, 0.014, aspect) * u_bloom * vec3(0.90, 0.97, 1.0);

    // 9. global light breathing (the surface moves -> light dims and brightens)
    c *= breath;

    // 10. vignette
    vec2  d   = v_uv - vec2(0.5, 0.54);
    float r   = length(vec2(d.x * 1.05, d.y * 1.25));
    float vig = (0.28 + 0.62 * s) * pow(clamp(r - 0.35, 0.0, 1.0), 2.0);
    c *= (1.0 - vig);

    // R0: HDR→LDR tonemap. The bloom/god-ray/emissive contributions above push c
    // past 1.0 in the RGBA16F buffer; the shoulder rolls those highlights off
    // (keeping their colour) before the 8-bit default framebuffer clips them.
    if (u_hdr == 1) c = tonemapShoulder(c);

    out_color = vec4(c, 1.0);
}
)glsl";

/* ── lookup table ───────────────────────────────────────────────────────── */

namespace OpenXcom { namespace Shaders {

struct Entry { const char* name; const char* vert; const char* frag; };

static const Entry kTable[] = {
    { "colorquad", kPassthroughVertSrc, kColorquadFragSrc },
    { "cursor", kCursorVertSrc, kCursorFragSrc },
    { "emissive_glow", kEmissive_glowVertSrc, kEmissive_glowFragSrc },
    { "globe_sphere", kGlobe_sphereVertSrc, kGlobe_sphereFragSrc },
    { "textured", kPassthroughVertSrc, kTexturedFragSrc },
    { "tile_atlas", kTile_atlasVertSrc, kTile_atlasFragSrc },
    { "tile_atlas_rgba", kTile_atlas_rgbaVertSrc, kTile_atlas_rgbaFragSrc },
    { "tile_blend", kTile_blendVertSrc, kTile_blendFragSrc },
    { "underwater_grade", kPassthroughVertSrc, kUnderwater_gradeFragSrc },
    { nullptr, nullptr, nullptr } /* sentinel */
};

ShaderPair findEmbedded(const char* name)
{
    if (!name) return { nullptr, nullptr };
    for (const Entry* e = kTable; e->name; ++e)
        if (strcmp(e->name, name) == 0)
            return { e->vert, e->frag };
    return { nullptr, nullptr };
}

} } // namespace OpenXcom::Shaders
